/**
 * Two columns that set life without the product against life with it, point by point. Axes: layout (cards: two
 * cards, rows: one row per point), icons (show, hide), tone, density.
 */
import { For, type JSX } from "solid-js";
import { Card } from "../primitives/card/card";
import { CardContent } from "../primitives/card/card-content";
import { Grid } from "../primitives/grid/grid";
import { Group } from "../primitives/group/group";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Contrast, BeforeAfterLabels } from "./before-after.types";

export type BeforeAfterProps = {
  id: string;
  title: string;
  points: Contrast[];
  labels: BeforeAfterLabels;
  layout?: "cards" | "rows";
  icons?: "show" | "hide";
  tone?: "default" | "muted";
  density?: "default" | "compact";
  landmarkLabel?: string;
};

export function BeforeAfter({
  id,
  title,
  points,
  labels,
  layout = "cards",
  icons = "show",
  tone = "default",
  density = "default",
  landmarkLabel,
}: BeforeAfterProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} density={density} landmarkLabel={landmarkLabel}>
      {((layout as string) === "cards") ? (
        <Grid cols="1-2" class="items-stretch gap-4" data-testid="sides">
          <Card
            variant="muted"
            class={cn("h-full", (((density as string) === "compact") ? "gap-4 p-4" : ""))}
            data-testid="side"
            data-side="before"
          >
            <CardContent class="flex flex-col gap-4">
              <Title as={3} size="xl" weight="bold">
                {labels.before}
              </Title>
              <List class="m-0 flex list-none flex-col gap-4 p-0">
                <For each={points ?? []}>{(p) => (
                  <ListItem class="flex items-start gap-4" data-testid="item">
                    {((icons as string) === "show") ? (
                      <LucideIcon name="x" size={16} class="h-lh shrink-0 text-sm" />
                    ) : null}
                    <Text size="sm">
                      {p.before}
                    </Text>
                  </ListItem>
                )}</For>
              </List>
            </CardContent>
          </Card>
          <Card
            variant="default"
            class={cn("h-full", (((density as string) === "compact") ? "gap-4 p-4" : ""))}
            data-testid="side"
            data-side="after"
          >
            <CardContent class="flex flex-col gap-4">
              <Title as={3} size="xl" weight="bold">
                {labels.after}
              </Title>
              <List class="m-0 flex list-none flex-col gap-4 p-0">
                <For each={points ?? []}>{(p) => (
                  <ListItem class="flex items-start gap-4" data-testid="item">
                    {((icons as string) === "show") ? (
                      <LucideIcon name="check" size={16} class="h-lh shrink-0 text-sm" />
                    ) : null}
                    <Text size="sm">
                      {p.after}
                    </Text>
                  </ListItem>
                )}</For>
              </List>
            </CardContent>
          </Card>
        </Grid>
      ) : (
        <Stack gap="2" align="stretch" data-testid="rows">
          <For each={points ?? []}>{(p) => (
            <Grid
              cols="1-3"
              class={cn("items-center gap-4", "rounded bg-card inset-ring inset-ring-border p-4")}
              data-testid="item"
            >
              <Text size="base" weight="semibold">
                {p.title}
              </Text>
              <Group gap="2" align="start">
                {((icons as string) === "show") ? (
                  <LucideIcon name="x" size={16} class="h-lh shrink-0 text-sm text-muted-foreground" />
                ) : null}
                <Text size="sm" class="text-muted-foreground">
                  {p.before}
                </Text>
              </Group>
              <Group gap="2" align="start">
                {((icons as string) === "show") ? (
                  <LucideIcon name="check" size={16} class="h-lh shrink-0 text-sm text-primary" />
                ) : null}
                <Text size="sm" weight="semibold">
                  {p.after}
                </Text>
              </Group>
            </Grid>
          )}</For>
        </Stack>
      )}
    </SectionFrame>
  );
}

